ASSETS=['map-gestures.js','gps-route-tools.js',*BASE]
def fixture():
    source=localize_html((STATIC/'tf-portal.html').read_text())
    assert 'href="/tf/stk-anlegen"' in source and 'id="routeTab-create"' not in source
